import { type Mode, modes } from '../index.ts';
import type { Oklch, Swatch } from './color.ts';
import { createRamp, type Ramp, stepNumbers, surfacesOf } from './ramp.ts';
import {
  type Colours,
  type Palette,
  palettes,
  type RampName,
  type RampSeed,
  ramps,
  statusInkHue,
  statusRamps,
} from './seeds.ts';

const generatedNote =
  'Generated by packages/tokens/scripts/generate.ts from src/palette/seeds.ts. Run pnpm run generate after changing a seed; never edit by hand.';

interface ColorToken {
  $type: 'color';
  $value:
    | { colorSpace: 'oklch'; components: [number, number, number]; alpha: number; hex: string }
    | string;
}

type RampGroup = Record<string, ColorToken>;
export type ModeRamps = Record<Mode, Ramp>;

function colorToken({ l, c, h, hex }: Swatch): ColorToken {
  return { $type: 'color', $value: { colorSpace: 'oklch', components: [l, c, h], alpha: 1, hex } };
}

function rampTokens(ramp: Ramp): RampGroup {
  const group: RampGroup = {};
  ramp.steps.forEach((step, index) => {
    group[String(index + 1)] = colorToken(step);
  });
  group.on = colorToken(ramp.on);
  return group;
}

function tokensByMode(rampsByMode: ModeRamps): Record<Mode, RampGroup> {
  return { light: rampTokens(rampsByMode.light), dark: rampTokens(rampsByMode.dark) };
}

function rampsOf(
  { seed, overrides = {} }: RampSeed,
  inkHue: number,
  backgrounds?: Record<Mode, Oklch[]>
): ModeRamps {
  const build = (mode: Mode) =>
    createRamp(seed, mode, {
      inkHue,
      overrides: overrides[mode],
      backgrounds: backgrounds?.[mode],
      readableOnSoft: backgrounds !== undefined,
    });
  return { light: build('light'), dark: build('dark') };
}

export function paletteRamps(colours: Colours): Record<RampName, ModeRamps> {
  const inkHue = colours.neutral.seed.h;
  const neutral = rampsOf(colours.neutral, inkHue);
  const surfaces = { light: surfacesOf(neutral.light), dark: surfacesOf(neutral.dark) };
  const accent = rampsOf(colours.accent, inkHue, surfaces);
  const [danger, success, warning, info] = statusRamps.map((name) =>
    rampsOf(colours.status[name], statusInkHue, surfaces)
  ) as [ModeRamps, ModeRamps, ModeRamps, ModeRamps];
  return { accent, neutral, danger, success, warning, info };
}

export function brandPalette(colours: Colours): object {
  const { accent, neutral } = paletteRamps(colours);
  return {
    $description: generatedNote,
    color: { palette: { accent: tokensByMode(accent), neutral: tokensByMode(neutral) } },
  };
}

export function statusPalette(colours: Colours): object {
  const generated = paletteRamps(colours);
  const palette: Record<string, Record<Mode, RampGroup>> = {};
  for (const name of statusRamps) {
    palette[name] = tokensByMode(generated[name]);
  }
  return { $description: generatedNote, color: { palette } };
}

function alias(ramp: RampName, mode: Mode, step: string): ColorToken {
  return { $type: 'color', $value: `{color.palette.${ramp}.${mode}.${step}}` };
}

export function scaleAliases(mode: Mode): object {
  const scale: Record<string, RampGroup> = {};
  for (const ramp of ramps) {
    const group: RampGroup = {};
    for (const step of stepNumbers) {
      group[String(step)] = alias(ramp, mode, String(step));
    }
    group.on = alias(ramp, mode, 'on');
    scale[ramp] = group;
  }
  return { $description: generatedNote, color: { scale } };
}

export function generatedFiles(): Record<string, object> {
  const files: Record<string, object> = {};
  for (const [name, colours] of Object.entries(palettes) as [Palette, Colours][]) {
    files[`${name}/palette-brand.tokens.json`] = brandPalette(colours);
    files[`${name}/palette-status.tokens.json`] = statusPalette(colours);
  }
  for (const mode of modes) {
    files[`scale-${mode}.tokens.json`] = scaleAliases(mode);
  }
  return files;
}

export function serialize(document: object): string {
  return `${JSON.stringify(document, null, 2)}\n`;
}
